// decodeObject 把 raw 解析为 JSON 对象；raw 不是单一 JSON 对象时返回 false。
// 对象前后允许 JSON 标准空白（空格、制表符、回车、换行）；对象结束后若还有
// 第二个 JSON 值或其他非空白文本，同样视为非法。字符串字段中的花括号属于
// 字段值，不影响判定。
func decodeObject(raw json.RawMessage) (map[string]json.RawMessage, bool) {
	trimmed := bytes.TrimLeft(raw, " \t\r\n")
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return nil, false
	}
	var obj map[string]json.RawMessage
	dec := json.NewDecoder(bytes.NewReader(raw))
	if err := dec.Decode(&obj); err != nil {
		return nil, false
	}
	if err := assertSingleValue(dec); err != nil {
		return nil, false
	}
	if obj == nil { // "null" 已通过首字符排除，这里防御性处理
		obj = map[string]json.RawMessage{}
	}
	return obj, true
}

func asObject(raw json.RawMessage) (map[string]json.RawMessage, bool) {
	return decodeObject(raw)
}

// assertSingleValue 确认解码器读完一个完整 JSON 值后只剩 JSON 空白：
// 第二个值解码成功（err == nil）或尾随文本无法解析（任何非 io.EOF 错误）
// 都表示输入不是单一 JSON 值，必须拒绝。
func assertSingleValue(dec *json.Decoder) error {
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		return errTrailingJSON
	}
	return nil
}

// validateConfig 校验配置必须是合法的 JSON 对象，并返回独立副本。
func validateConfig(raw json.RawMessage) (json.RawMessage, error) {
	if _, ok := decodeObject(raw); !ok {
		return nil, ErrInvalidConfig
	}
	return cloneRaw(raw), nil
}

// rawEqual 比较两份 JSON 值是否语义相等：忽略对象字段顺序，
// 数字按数值比较（1 与 1.0 相等），其余按类型与值比较。
func rawEqual(a, b json.RawMessage) bool {
	av, err := decodeValue(a)
	if err != nil {
		return false
	}
	bv, err := decodeValue(b)
	if err != nil {
		return false
	}
	return jsonDeepEqual(av, bv)
}

func decodeValue(raw json.RawMessage) (any, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	if err := assertSingleValue(dec); err != nil {
		return nil, err
	}
	return v, nil
}

func jsonDeepEqual(a, b any) bool {
	switch av := a.(type) {
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, va := range av {
			vb, ok := bv[k]
			if !ok || !jsonDeepEqual(va, vb) {
				return false
			}
		}
		return true
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !jsonDeepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case json.Number:
		bv, ok := b.(json.Number)
		if !ok {
			return false
		}
		return numberEqual(av, bv)
	default:
		return reflect.DeepEqual(a, b)
	}
}

func numberEqual(a, b json.Number) bool {
	if a.String() == b.String() {
		return true
	}
	ra, okA := new(big.Rat).SetString(a.String())
	rb, okB := new(big.Rat).SetString(b.String())
	if okA && okB {
		return ra.Cmp(rb) == 0
	}
	return false
}

func cloneRaw(raw json.RawMessage) json.RawMessage {
	if raw == nil {
		return nil
	}
	out := make(json.RawMessage, len(raw))
	copy(out, raw)
	return out
}

