287	// 才重新计时，且恢复出的计时记录与正常流程产生的记录行为一致。
288	func TestRestoreDiffSinceLifecycleAcrossReopen(t *testing.T) {
289		t1 := base
290		s, dir := openTemp(t)
291		mustRegister(t, s, "dev-1", "1.0")
292		if _, err := s.UpdateDesired("dev-1", "op", t1, 0, json.RawMessage(`{"a":1}`)); err != nil {
