308		t2 := base.Add(time.Minute)
309		if _, err := s2.UpdateDesired("dev-1", "op", t2, 1, json.RawMessage(`{"a":2}`)); err != nil {
310			t.Fatal(err)
311		}
312		if diffs, _ := s2.Diff("dev-1"); !diffs[0].Since.Equal(t1) {
313			t.Fatalf("persistent diff must keep original time: %+v", diffs)
314		}
315		// 差异消失，关闭重开：无差异、无计时记录仍合法。
316		t3 := base.Add(2 * time.Minute)
317		if err := s2.Report("dev-1", 1, t3, "1.0", json.RawMessage(`{"a":2}`)); err != nil {
318			t.Fatal(err)
319		}
320		if err := s2.Close(); err != nil {
321			t.Fatal(err)
322		}
323		s3, err := Open(dir)
324		if err != nil {
325			t.Fatalf("reopen without diffs: %v", err)
326		}
327		if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
328			t.Fatalf("cleared diff must stay cleared: %+v", diffs)
329		}
330		// 同一路径再次出现差异：必须重新计时，不能沿用消失前的 t1。
331		t4 := base.Add(3 * time.Minute)
332		if _, err := s3.UpdateDesired("dev-1", "op", t4, 2, json.RawMessage(`{"a":3}`)); err != nil {
333			t.Fatal(err)
334		}
335		if err := s3.Close(); err != nil {
336			t.Fatal(err)
337		}
338		s4, err := Open(dir)
339		if err != nil {
340			t.Fatalf("final reopen: %v", err)
341		}
342		defer s4.Close()
343		diffs, _ := s4.Diff("dev-1")
344		if len(diffs) != 1 || diffs[0].Path != "/a" || !diffs[0].Since.Equal(t4) {
345			t.Fatalf("reappeared diff must restart timing at t4: %+v", diffs)
346		}
347	}
