		"never reported with empty version": func(doc fixStore) {
			d := neverReportedDoc().Devices["dev-1"]
			d.Version = ""
			doc.Devices["dev-1"] = d
		},
		// 已上报设备版本为空。
		"reported with empty version": func(doc fixStore) {
			d := reportedDoc().Devices["dev-1"]
			d.Version = ""
			doc.Devices["dev-1"] = d
		},
	}
